DROP TABLE IF EXISTS `sys_permission`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_permission` (
  `id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci NOT NULL COMMENT 'primary keyid',
  `parent_id` varchar(32) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'fatherid',
  `name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'menutitle',
  `url` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'path',
  `component` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'components',
  `is_route` tinyint(1) DEFAULT '1' COMMENT 'yesno路Depend onmenu: 0:不yes  1:yes（defaultvalue1）',
  `component_name` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'components名Character',
  `redirect` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT '一级menuJumpaddress',
  `menu_type` int DEFAULT NULL COMMENT 'menutype(0:一级menu; 1:子menu:2:Button permissions)',
  `perms` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'menuPermissionscoding',
  `perms_type` varchar(10) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT '0' COMMENT 'Permission policy1show2Disable',
  `sort_no` double(8,2) DEFAULT NULL COMMENT 'menusort',
  `always_show` tinyint(1) DEFAULT NULL COMMENT '聚合子路Depend on: 1yes0no',
  `icon` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'menuicon',
  `is_leaf` tinyint(1) DEFAULT NULL COMMENT 'yesno叶子node:    1yes0no',
  `keep_alive` tinyint(1) DEFAULT NULL COMMENT 'yesnocache该page:    1:yes   0:不yes',
  `hidden` tinyint DEFAULT '0' COMMENT 'yesnoHidden route: 0no,1yes',
  `hide_tab` tinyint DEFAULT NULL COMMENT 'yesno隐藏tab: 0no,1yes',
  `description` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'describe',
  `create_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'Creator',
  `create_time` datetime DEFAULT NULL COMMENT '创建hour间',
  `update_by` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'Updater',
  `update_time` datetime DEFAULT NULL COMMENT 'renewhour间',
  `del_flag` int DEFAULT '0' COMMENT 'deletestate 0normal 1已delete',
  `rule_flag` int DEFAULT '0' COMMENT 'yesnoAdd todataPermissions1yes0no',
  `status` varchar(2) CHARACTER SET utf8mb3 COLLATE utf8mb3_general_ci DEFAULT NULL COMMENT 'Button permissionsstate(0none效1efficient)',
  `internal_or_external` tinyint(1) DEFAULT NULL COMMENT 'outside链menuOpen method 0/内departmentOpen 1/outsidedepartmentOpen',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `index_menu_type` (`menu_type`) USING BTREE,
  KEY `index_menu_hidden` (`hidden`) USING BTREE,
  KEY `index_menu_status` (`status`) USING BTREE,
  KEY `index_menu_del_flag` (`del_flag`) USING BTREE,
  KEY `index_menu_url` (`url`) USING BTREE,
  KEY `index_menu_sort_no` (`sort_no`) USING BTREE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 ROW_FORMAT=DYNAMIC COMMENT='menuPermissionssurface';
